CREATE TABLE IF NOT EXISTS users (id TEXT PRIMARY KEY, email TEXT UNIQUE NOT NULL, password_hash TEXT NOT NULL, name TEXT DEFAULT '', role TEXT NOT NULL DEFAULT 'user', created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS sessions (token_hash TEXT PRIMARY KEY, user_id TEXT NOT NULL, expires_at INTEGER NOT NULL, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS stories (id TEXT PRIMARY KEY, title TEXT NOT NULL, category TEXT NOT NULL, emoji TEXT DEFAULT '📖', excerpt TEXT DEFAULT '', content TEXT NOT NULL, lesson TEXT DEFAULT '', image_url TEXT DEFAULT '', video_url TEXT DEFAULT '', views INTEGER NOT NULL DEFAULT 0, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS posts (id TEXT PRIMARY KEY, type TEXT NOT NULL CHECK(type IN ('news','blog')), title TEXT NOT NULL, category TEXT DEFAULT '', excerpt TEXT DEFAULT '', content TEXT NOT NULL, image_url TEXT DEFAULT '', status TEXT NOT NULL DEFAULT 'published', published_at TEXT, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS submissions (id TEXT PRIMARY KEY, user_id TEXT, author_name TEXT NOT NULL, title TEXT NOT NULL, category TEXT NOT NULL, excerpt TEXT DEFAULT '', content TEXT NOT NULL, lesson TEXT DEFAULT '', image_url TEXT DEFAULT '', video_url TEXT DEFAULT '', status TEXT NOT NULL DEFAULT 'pending', created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS chat_messages (id TEXT PRIMARY KEY, room_id TEXT NOT NULL DEFAULT 'public', user_id TEXT NOT NULL, message TEXT NOT NULL, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS page_views (id INTEGER PRIMARY KEY AUTOINCREMENT, path TEXT NOT NULL, story_id TEXT, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE INDEX IF NOT EXISTS idx_stories_created ON stories(created_at DESC);
CREATE INDEX IF NOT EXISTS idx_posts_type_status ON posts(type,status,published_at DESC);
CREATE INDEX IF NOT EXISTS idx_submissions_status ON submissions(status,created_at DESC);
CREATE INDEX IF NOT EXISTS idx_chat_created ON chat_messages(room_id,created_at);
